import { useState } from 'react';

function Profile() {
  const [profile, setProfile] = useState({ name: 'Ada', theme: 'light' });

  function toggleTheme() {
    setProfile({ ...profile, theme: profile.theme === 'light' ? 'dark' : 'light' });
  }

  return (
    <button onClick={toggleTheme}>
      {profile.name} uses the {profile.theme} theme
    </button>
  );
}

import { useState } from 'react';

function Tags() {
  const [tags, setTags] = useState(['react']);

  const add = (tag) => setTags([...tags, tag]);
  const remove = (tag) => setTags(tags.filter((t) => t !== tag));

  return (
    <>
      <ul>{tags.map((t) => <li key={t}>{t}</li>)}</ul>
      <button onClick={() => add('vite')}>Add vite</button>
      <button onClick={() => remove('react')}>Remove react</button>
    </>
  );
}

import { useState } from 'react';

function TemperatureInput({ value, onChange }) {
  return <input value={value} onChange={(e) => onChange(e.target.value)} />;
}

function Converter() {
  const [celsius, setCelsius] = useState('20');
  const fahrenheit = (Number(celsius) * 9) / 5 + 32;

  return (
    <>
      <TemperatureInput value={celsius} onChange={setCelsius} />
      <p>{celsius} °C is {fahrenheit} °F</p>
    </>
  );
}
